def model_slug(model_id: str) -> str:
    lower = model_id.lower()
    if "olmo" in lower:
        return "olmo2"
    if "ministral" in lower:
        return "ministral"
    if "mistral" in lower:
        return "mistral"
    if "qwen" in lower:
        return "qwen"
    if "gemma" in lower:
        return "gemma"
    return (
        model_id.lower()
        .replace("/", "_")
        .replace("-", "_")
        .replace(".", "_")
    )[:48]


MODEL_SLUG = model_slug(MODEL_ID)
