def save_text(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8")
    print("saved:", path)


def safe_sheet_name(name: str, used: set[str]) -> str:
    invalid = set(r'[]:*?/\\')
    cleaned = "".join("_" if ch in invalid else ch for ch in str(name)).strip()
    cleaned = cleaned or "sheet"
    base = cleaned[:31]
    candidate = base
    counter = 2
    while candidate in used:
        suffix = f"_{counter}"
        candidate = base[:31 - len(suffix)] + suffix
        counter += 1
    used.add(candidate)
    return candidate


def excel_ready_df(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty and len(df.columns) == 0:
        return pd.DataFrame({"note": ["empty"]})
    work = df.copy()
    for col in work.columns:
        if work[col].dtype == "object":
            work[col] = work[col].map(
                lambda value: json.dumps(value, ensure_ascii=False)
                if isinstance(value, (dict, list, tuple))
                else value
            )
    return work


def save_xlsx_tables(path: Path, tables: dict[str, pd.DataFrame]) -> None:
    with pd.ExcelWriter(path, engine="openpyxl") as writer:
        used: set[str] = set()
        for requested_name, df in tables.items():
            sheet_name = safe_sheet_name(requested_name, used)
            work = excel_ready_df(df)
            work.to_excel(writer, sheet_name=sheet_name, index=False)
            worksheet = writer.sheets[sheet_name]
            worksheet.freeze_panes = "A2"
            if worksheet.max_row >= 1 and worksheet.max_column >= 1:
                worksheet.auto_filter.ref = worksheet.dimensions
            for column_cells in worksheet.columns:
                header = str(column_cells[0].value or "")
                width = len(header) + 2
                for cell in column_cells[1:101]:
                    if cell.value is not None:
                        width = max(width, min(len(str(cell.value)) + 2, 80))
                worksheet.column_dimensions[column_cells[0].column_letter].width = min(max(width, 10), 80)
    print("saved:", path)


def repeat_seed_to_token_length(seed_text: str, target_text: str) -> str:
    target_n = len(tokenizer.encode(target_text, add_special_tokens=False))
    seed_ids = tokenizer.encode(seed_text.strip() + "\n", add_special_tokens=False)
    repeats = math.ceil(target_n / max(1, len(seed_ids))) + 1
    ids = (seed_ids * repeats)[:target_n]
    return tokenizer.decode(ids, skip_special_tokens=True)


def make_inline_content_matched_control(target_text: str, target_label: str | None = None) -> str:
    label_key = str(target_label) if target_label is not None else "_default"
    seed_text = INLINE_CONTENT_MATCHED_CONTROL_SEEDS.get(
        label_key,
        INLINE_CONTENT_MATCHED_CONTROL_SEEDS.get("_default", "Neutral control text."),
    )
    return repeat_seed_to_token_length(seed_text, target_text)


def load_input_texts() -> tuple[list[str], list[str], list[str], dict[str, Any]]:
    inline_targets = [str(x).strip() for x in INLINE_TARGET_TEXTS if str(x).strip()] if USE_INLINE_TEXTS else []
    inline_controls = [str(x).strip() for x in INLINE_CONTROL_TEXTS if str(x).strip()] if USE_INLINE_TEXTS else []
    if inline_targets or inline_controls:
        labels = [str(x) for x in INLINE_TARGET_LABELS]
        if len(labels) != len(inline_targets):
            labels = [f"inline_{i}" for i in range(len(inline_targets))]
        if inline_targets and not inline_controls:
            inline_controls = [
                make_inline_content_matched_control(
                    text,
                    labels[i] if i < len(labels) else None,
                )
                for i, text in enumerate(inline_targets)
            ]
            control_source = "inline_auto:content_matched"
            control_mode = "content_matched"
        else:
            control_source = "inline_manual"
            control_mode = "inline_manual"
        if len(inline_targets) != len(inline_controls):
            raise ValueError(
                "INLINE_TARGET_TEXTS and INLINE_CONTROL_TEXTS must have the same "
                "number of non-empty entries, unless INLINE_CONTROL_TEXTS is empty "
                "and auto content-matched controls are used."
            )
        input_metadata = {
            "input_texts_path": "INLINE_TARGET_TEXTS plus generated controls",
            "input_primary_control_mode": control_mode,
            "input_control_texts_source": control_source,
            "input_text_family_preset": "original_selfref_inline",
            "input_content_matched_control_labels": labels,
        }
        print("loaded input texts from inline script lists")
        print("inline control source:", control_source)
        return inline_targets, inline_controls, labels, input_metadata

    for path in INPUT_TEXTS_CANDIDATES:
        if path.exists():
            data = json.loads(path.read_text(encoding="utf-8"))
            target_texts = [str(x).strip() for x in data["target_texts"] if str(x).strip()]
            control_texts = [str(x).strip() for x in data["control_texts"] if str(x).strip()]
            labels = [str(x) for x in data.get("target_labels", [])]
            if len(labels) != len(target_texts):
                labels = [f"text_{i}" for i in range(len(target_texts))]
            control_seed_labels = data.get("content_matched_control_seeds", {})
            if isinstance(control_seed_labels, dict):
                control_seed_labels = list(control_seed_labels.keys())
            input_metadata = {
                "input_texts_path": str(path),
                "input_primary_control_mode": data.get("primary_control_mode", ""),
                "input_control_texts_source": data.get("control_texts_source", ""),
                "input_text_family_preset": data.get("text_family_preset", ""),
                "input_content_matched_control_labels": control_seed_labels,
            }
            print("loaded input texts from:", path)
            if input_metadata["input_primary_control_mode"]:
                print("input primary control mode:", input_metadata["input_primary_control_mode"])
            if input_metadata["input_control_texts_source"]:
                print("input control source:", input_metadata["input_control_texts_source"])
            return target_texts, control_texts, labels, input_metadata
    raise FileNotFoundError(
        "Could not find input texts. Set INPUT_TEXTS_PATH to a JSON file with "
        "target_texts/control_texts."
    )


