def model_from_pretrained(model_cls):
    kwargs = {
        "trust_remote_code": True,
        "dtype": dtype,
    }
    try:
        return model_cls.from_pretrained(MODEL_ID, **kwargs)
    except TypeError:
        kwargs.pop("dtype", None)
        kwargs["torch_dtype"] = dtype
        return model_cls.from_pretrained(MODEL_ID, **kwargs)


