def build_chat_messages(messages: list[dict[str, str]], add_generation_prompt: bool = True) -> str:
    if hasattr(tokenizer, "apply_chat_template") and tokenizer.chat_template:
        try:
            return tokenizer.apply_chat_template(
                messages,
                tokenize=False,
                add_generation_prompt=add_generation_prompt,
                **CHAT_TEMPLATE_KWARGS,
            )
        except TypeError:
            return tokenizer.apply_chat_template(
                messages,
                tokenize=False,
                add_generation_prompt=add_generation_prompt,
            )
    rendered = []
    for message in messages:
        role = str(message.get("role", "user")).capitalize()
        rendered.append(f"{role}: {message.get('content', '')}")
    return "\n".join(rendered) + ("\nAssistant:" if add_generation_prompt else "")


def tokenized_prompt(prompt: str, *, truncation: bool = True):
    kwargs = {
        "return_tensors": "pt",
        "truncation": truncation,
    }
    if truncation:
        kwargs["max_length"] = MAX_TOKENS
    return tokenizer(prompt, **kwargs)


def token_count_for_prompt(prompt: str) -> int:
    return int(tokenized_prompt(prompt, truncation=False).input_ids.shape[1])


def adjusted_anchor_index(
    prefix_messages: list[dict[str, str]],
    full_messages: list[dict[str, str]],
) -> dict[str, Any]:
    prefix_prompt = build_chat_messages(prefix_messages, add_generation_prompt=False)
    full_prompt = build_chat_messages(full_messages, add_generation_prompt=True)
    prefix_len = token_count_for_prompt(prefix_prompt)
    full_len = token_count_for_prompt(full_prompt)
    kept_len = min(full_len, MAX_TOKENS)
    if tokenizer.truncation_side == "left":
        truncation_offset = max(0, full_len - MAX_TOKENS)
    else:
        truncation_offset = 0
    raw_anchor_index = max(0, prefix_len - 1)
    adjusted = raw_anchor_index - truncation_offset
    anchor_available = 0 <= adjusted < kept_len
    return {
        "anchor_token_index": int(adjusted),
        "raw_anchor_token_index": int(raw_anchor_index),
        "prefix_token_count": int(prefix_len),
        "full_token_count": int(full_len),
        "truncation_offset": int(truncation_offset),
        "anchor_available": bool(anchor_available),
    }


def extract_hidden_states(out) -> tuple[torch.Tensor, ...]:
    hidden_states = getattr(out, "hidden_states", None)
    if hidden_states is None and hasattr(out, "language_model_outputs"):
        hidden_states = getattr(out.language_model_outputs, "hidden_states", None)
    if hidden_states is None:
        raise TypeError("Model output did not expose hidden_states.")
    return hidden_states


def make_add_token_hook(token_index: int, vector: torch.Tensor):
    def hook(_module, _inputs, output):
        if isinstance(output, tuple):
            hidden = output[0].clone()
            pos = int(token_index)
            if pos < 0:
                pos = hidden.shape[1] + pos
            pos = max(0, min(pos, hidden.shape[1] - 1))
            add = vector.to(hidden.device, hidden.dtype).view(1, 1, -1)
            hidden[:, pos:pos + 1, :] = hidden[:, pos:pos + 1, :] + add
            return (hidden,) + output[1:]
        hidden = output.clone()
        pos = int(token_index)
        if pos < 0:
            pos = hidden.shape[1] + pos
        pos = max(0, min(pos, hidden.shape[1] - 1))
        add = vector.to(hidden.device, hidden.dtype).view(1, 1, -1)
        hidden[:, pos:pos + 1, :] = hidden[:, pos:pos + 1, :] + add
        return hidden

    return hook


@torch.no_grad()
def hidden_by_messages(
    messages: list[dict[str, str]],
    *,
    hook_module_layer: int | None = None,
    hook_token_index: int | None = None,
    hook_vector: torch.Tensor | None = None,
) -> tuple[np.ndarray, int, bool]:
    prompt = build_chat_messages(messages, add_generation_prompt=True)
    inputs = tokenized_prompt(prompt, truncation=True).to(device)
    prompt_tokens = int(inputs.input_ids.shape[1])
    handle = None
    try:
        if hook_module_layer is not None and hook_token_index is not None and hook_vector is not None:
            handle = decoder_layers[int(hook_module_layer)].register_forward_hook(
                make_add_token_hook(int(hook_token_index), hook_vector)
            )
        out = model(**inputs, output_hidden_states=True, use_cache=False)
        hs = extract_hidden_states(out)
    finally:
        if handle is not None:
            handle.remove()
    stacked = torch.stack([h[0, -1, :].float().cpu() for h in hs], dim=0).numpy()
    return stacked, prompt_tokens, bool(prompt_tokens >= MAX_TOKENS)


def intro_message(text: str) -> dict[str, str]:
    return {"role": "user", "content": INTRO_TEMPLATE.format(text=text)}


def add_neutral_recovery(messages: list[dict[str, str]], recovery_turns: int) -> list[dict[str, str]]:
    out = list(messages)
    for turn_idx in range(recovery_turns):
        if out[-1]["role"] == "user":
            out.append({"role": "assistant", "content": FIXED_ASSISTANT})
        filler = NEUTRAL_FILLER_TASKS[turn_idx % len(NEUTRAL_FILLER_TASKS)]
        out.append({"role": "user", "content": filler})
    return out


def build_condition_messages(
    target_text: str,
    control_text: str,
    condition: str,
    recovery_turns: int,
) -> list[dict[str, str]]:
    messages = [{"role": "system", "content": SYSTEM_PROMPT}]

    if condition == "T_neutral":
        messages.append(intro_message(target_text))
        return add_neutral_recovery(messages, recovery_turns)

    if condition == "C_neutral":
        messages.append(intro_message(control_text))
        return add_neutral_recovery(messages, recovery_turns)

    if condition == "T_rejection":
        messages.append(intro_message(target_text))
        messages.append({"role": "assistant", "content": FIXED_ASSISTANT})
        messages.append({"role": "user", "content": REJECTION_USER_MESSAGE})
        return add_neutral_recovery(messages, recovery_turns)

    if condition == "T_control":
        messages.append(intro_message(target_text))
        messages.append({"role": "assistant", "content": FIXED_ASSISTANT})
        messages.append(intro_message(control_text))
        return add_neutral_recovery(messages, recovery_turns)

    if condition == "T_unrelated":
        messages.append(intro_message(target_text))
        messages.append({"role": "assistant", "content": FIXED_ASSISTANT})
        messages.append({"role": "user", "content": UNRELATED_PERTURBATION_MESSAGE})
        return add_neutral_recovery(messages, recovery_turns)

    if condition == "C_target":
        messages.append(intro_message(control_text))
        messages.append({"role": "assistant", "content": FIXED_ASSISTANT})
        messages.append(intro_message(target_text))
        return add_neutral_recovery(messages, recovery_turns)

    raise ValueError(f"Unknown condition: {condition}")


def cosine(a: np.ndarray, b: np.ndarray) -> float:
    denom = np.linalg.norm(a) * np.linalg.norm(b) + 1e-12
    return float(np.dot(a, b) / denom)


def euclidean(a: np.ndarray, b: np.ndarray) -> float:
    return float(np.linalg.norm(a - b))


def target_closeness_from_distances(distance_to_target: float, distance_to_control: float) -> float:
    denom = distance_to_target + distance_to_control + 1e-12
    return float(distance_to_control / denom)


def bootstrap_mean(values: np.ndarray, units: np.ndarray) -> dict[str, Any]:
    mask = np.isfinite(values)
    values = values[mask].astype(float)
    units = units[mask]
    unique_units = np.array(sorted(set(units.tolist())))
    if values.size == 0 or unique_units.size == 0:
        return {"mean": np.nan, "ci_low": np.nan, "ci_high": np.nan, "n_units": 0, "n_rows": 0}
    grouped = {u: values[units == u] for u in unique_units}
    observed = float(np.mean(values))
    rng = np.random.default_rng(BOOTSTRAP_SEED)
    boot = np.empty(BOOTSTRAP_N, dtype=float)
    for b in range(BOOTSTRAP_N):
        sampled = rng.choice(unique_units, size=unique_units.size, replace=True)
        boot[b] = float(np.mean(np.concatenate([grouped[u] for u in sampled])))
    return {
        "mean": observed,
        "ci_low": float(np.quantile(boot, 0.025)),
        "ci_high": float(np.quantile(boot, 0.975)),
        "n_units": int(unique_units.size),
        "n_rows": int(values.size),
    }


def pairwise_mean_distance(vectors: list[np.ndarray]) -> float:
    if len(vectors) < 2:
        return float("nan")
    distances = [euclidean(a, b) for a, b in itertools.combinations(vectors, 2)]
    return float(np.mean(distances))


def pairwise_max_distance(vectors: list[np.ndarray]) -> float:
    if len(vectors) < 2:
        return float("nan")
    distances = [euclidean(a, b) for a, b in itertools.combinations(vectors, 2)]
    return float(np.max(distances))


