print("\nCollecting target/control reference states...")
target_ref = []
control_ref = []
ref_meta_rows = []

for i, (target_text, control_text) in enumerate(zip(TARGET_TEXTS, CONTROL_TEXTS)):
    label = TARGET_LABELS[i]
    if i % 1 == 0:
        print("reference pair", i + 1, "/", len(TARGET_TEXTS), label)
    h_t, tok_t, trunc_t = hidden_by_messages(build_condition_messages(target_text, control_text, "T_neutral", 0))
    h_c, tok_c, trunc_c = hidden_by_messages(build_condition_messages(target_text, control_text, "C_neutral", 0))
    target_ref.append(h_t)
    control_ref.append(h_c)
    ref_meta_rows.extend([
        {"kind": "target", "index": i, "target_label": label, "prompt_tokens": tok_t, "truncated_risk": trunc_t},
        {"kind": "control", "index": i, "target_label": label, "prompt_tokens": tok_c, "truncated_risk": trunc_c},
    ])

target_H = np.stack(target_ref, axis=0)
control_H = np.stack(control_ref, axis=0)
target_mean = target_H.mean(axis=0)
control_mean = control_H.mean(axis=0)
contrast = target_mean - control_mean

layer_rows = []
for hidden_index in range(target_mean.shape[0]):
    target_norm = float(np.linalg.norm(target_mean[hidden_index]))
    control_norm = float(np.linalg.norm(control_mean[hidden_index]))
    mean_norm = (target_norm + control_norm) / 2.0
    contrast_norm = float(np.linalg.norm(contrast[hidden_index]))
    c = cosine(target_mean[hidden_index], control_mean[hidden_index])
    layer_rows.append({
        "hidden_index": hidden_index,
        "module_layer": hidden_index - 1,
        "contrast_norm": contrast_norm,
        "target_norm": target_norm,
        "control_norm": control_norm,
        "mean_state_norm": mean_norm,
        "contrast_over_mean_norm": contrast_norm / (mean_norm + 1e-12),
        "centroid_cosine": c,
        "cosine_distance": 1.0 - c,
    })

df_layers = pd.DataFrame(layer_rows)
save_df(pd.DataFrame(ref_meta_rows), "reference_prompt_metadata.csv")
save_df(df_layers, "basin_layer_map.csv")

top_hidden = (
    df_layers[df_layers["hidden_index"] > 0]
    .sort_values("contrast_over_mean_norm", ascending=False)["hidden_index"]
    .head(TOP_LAYER_COUNT)
    .astype(int)
    .tolist()
)
final_hidden = int(target_mean.shape[0] - 1)
selected_hidden_indices = []
for value in [*top_hidden, final_hidden]:
    if value > 0 and value not in selected_hidden_indices:
        selected_hidden_indices.append(value)
print("selected hidden indices:", selected_hidden_indices)

target_region_rows = []
target_radius_by_hidden: dict[int, float] = {}
control_radius_by_hidden: dict[int, float] = {}
for hidden_index in selected_hidden_indices:
    target_distances = np.linalg.norm(target_H[:, hidden_index, :] - target_mean[hidden_index], axis=1)
    control_distances = np.linalg.norm(control_H[:, hidden_index, :] - control_mean[hidden_index], axis=1)
    target_radius = float(np.quantile(target_distances, STRICT_REGION_RADIUS_QUANTILE) * STRICT_REGION_RADIUS_MULTIPLIER)
    control_radius = float(np.quantile(control_distances, STRICT_REGION_RADIUS_QUANTILE) * STRICT_REGION_RADIUS_MULTIPLIER)
    target_radius_by_hidden[hidden_index] = target_radius
    control_radius_by_hidden[hidden_index] = control_radius
    target_region_rows.append({
        "hidden_index": hidden_index,
        "module_layer": hidden_index - 1,
        "target_region_radius": target_radius,
        "control_region_radius": control_radius,
        "radius_quantile": STRICT_REGION_RADIUS_QUANTILE,
        "radius_multiplier": STRICT_REGION_RADIUS_MULTIPLIER,
        "target_ref_inside_rate": float(np.mean(target_distances <= target_radius)),
        "control_ref_inside_own_rate": float(np.mean(control_distances <= control_radius)),
        "control_ref_inside_target_rate": float(np.mean(
            np.linalg.norm(control_H[:, hidden_index, :] - target_mean[hidden_index], axis=1) <= target_radius
        )),
        "target_ref_inside_control_rate": float(np.mean(
            np.linalg.norm(target_H[:, hidden_index, :] - control_mean[hidden_index], axis=1) <= control_radius
        )),
        "target_ref_mean_distance_to_target": float(np.mean(target_distances)),
        "control_ref_mean_distance_to_control": float(np.mean(control_distances)),
    })
df_target_region = pd.DataFrame(target_region_rows)
save_df(df_target_region, "strict_target_region_map.csv")


