def clipped_token_ids(text: str, budget: int) -> list[int]:
    ids = tokenizer.encode(text, add_special_tokens=False)
    if len(ids) <= budget:
        return ids
    half = budget // 2
    return ids[:half] + ids[-(budget - half):]


def mix_text(target_text: str, control_text: str, target_fraction: float, order: str) -> str:
    target_ids = clipped_token_ids(target_text, MIX_TOKEN_BUDGET)
    control_ids = clipped_token_ids(control_text, MIX_TOKEN_BUDGET)
    total = min(len(target_ids), len(control_ids), MIX_TOKEN_BUDGET)
    if total <= 0:
        return ""
    n_target = int(round(total * target_fraction))
    n_control = total - n_target
    if order == "target_prefix":
        ids = target_ids[:n_target] + control_ids[-n_control:] if n_control > 0 else target_ids[:n_target]
    elif order == "target_suffix":
        ids = control_ids[:n_control] + target_ids[-n_target:] if n_target > 0 else control_ids[:n_control]
    else:
        raise ValueError(f"Unknown mix order: {order}")
    return tokenizer.decode(ids, skip_special_tokens=True)


