def normalize_to_norm(vector: np.ndarray, target_norm: float) -> np.ndarray:
    norm = float(np.linalg.norm(vector))
    if norm <= 1e-12:
        return vector
    return vector * (target_norm / norm)


def strict_perturbation_vectors(hidden_index: int, alpha: float) -> list[dict[str, Any]]:
    base = np.asarray(contrast[hidden_index], dtype=np.float64)
    base_norm = float(np.linalg.norm(base))
    target_norm = float(alpha) * base_norm
    if target_norm <= 1e-12:
        return []

    seed_base = STRICT_HIDDEN_PERTURB_SEED + hidden_index * 1009 + int(round(float(alpha) * 1000))
    rng = np.random.default_rng(seed_base)
    vectors: list[dict[str, Any]] = [
        {
            "perturb_kind": "toward_control",
            "perturb_seed": -1,
            "vector": normalize_to_norm(-base, target_norm),
        },
        {
            "perturb_kind": "away_from_control",
            "perturb_seed": -2,
            "vector": normalize_to_norm(base, target_norm),
        },
    ]
    for rep in range(STRICT_HIDDEN_PERTURB_REPLICATES):
        random_vec = rng.normal(size=base.shape)
        vectors.append({
            "perturb_kind": "random_same_norm",
            "perturb_seed": rep,
            "vector": normalize_to_norm(random_vec, target_norm),
        })

        orthogonal = random_vec.copy()
        denom = float(np.dot(base, base))
        if denom > 1e-12:
            orthogonal = orthogonal - (float(np.dot(orthogonal, base)) / denom) * base
        vectors.append({
            "perturb_kind": "orthogonal_random",
            "perturb_seed": rep,
            "vector": normalize_to_norm(orthogonal, target_norm),
        })
    return vectors


def strict_jacobian_unit_directions(hidden_index: int, n_directions: int) -> list[dict[str, Any]]:
    base = np.asarray(contrast[hidden_index], dtype=np.float64)
    directions: list[dict[str, Any]] = []
    basis: list[np.ndarray] = []

    def add_direction(name: str, seed: int, vector: np.ndarray) -> None:
        work = np.asarray(vector, dtype=np.float64)
        for prior in basis:
            work = work - float(np.dot(work, prior)) * prior
        norm = float(np.linalg.norm(work))
        if norm <= 1e-12:
            return
        unit = work / norm
        basis.append(unit)
        directions.append({
            "direction_name": name,
            "direction_seed": int(seed),
            "unit_vector": unit,
        })

    add_direction("target_control", -1, base)
    rng = np.random.default_rng(STRICT_HIDDEN_PERTURB_SEED + hidden_index * 7919 + 17)
    attempts = 0
    while len(directions) < int(n_directions) and attempts < int(n_directions) * 20:
        random_vec = rng.normal(size=base.shape)
        add_direction("orthonormal_random", attempts, random_vec)
        attempts += 1
    return directions


def closest_alpha(requested: float, available: list[float]) -> float:
    if not available:
        return float("nan")
    return float(min(available, key=lambda value: abs(float(value) - float(requested))))


