df_strict_jacobian_raw = pd.DataFrame(strict_jacobian_rows)
if df_strict_jacobian_raw.empty:
    save_df(pd.DataFrame(), "strict_local_jacobian_raw.csv")
    df_strict_jacobian_spectral_raw = pd.DataFrame()
    save_df(df_strict_jacobian_spectral_raw, "strict_local_jacobian_spectral_raw.csv")
    df_strict_jacobian_summary = pd.DataFrame()
    save_df(df_strict_jacobian_summary, "strict_local_jacobian_summary.csv")
else:
    save_df(df_strict_jacobian_raw, "strict_local_jacobian_raw.csv")
    jacobian_vector_groups: dict[tuple[Any, ...], list[np.ndarray]] = {}
    for row in strict_jacobian_vector_rows:
        key = (
            int(row["index"]),
            row["target_label"],
            row["start_kind"],
            row["condition"],
            int(row["recovery_turns"]),
            int(row["hidden_index"]),
            int(row["module_layer"]),
            int(row["perturb_hidden_index"]),
            int(row["perturb_module_layer"]),
        )
        jacobian_vector_groups.setdefault(key, []).append(np.asarray(row["derivative_vector"], dtype=np.float32))

    spectral_rows = []
    for keys, derivative_vectors in jacobian_vector_groups.items():
        matrix = np.stack(derivative_vectors, axis=1).astype(np.float64)
        singular_values = np.linalg.svd(matrix, compute_uv=False)
        spectral_rows.append({
            "index": int(keys[0]),
            "target_label": keys[1],
            "start_kind": keys[2],
            "condition": keys[3],
            "recovery_turns": int(keys[4]),
            "hidden_index": int(keys[5]),
            "module_layer": int(keys[6]),
            "perturb_hidden_index": int(keys[7]),
            "perturb_module_layer": int(keys[8]),
            "local_jacobian_spectral_norm": float(singular_values[0]) if singular_values.size else np.nan,
            "local_jacobian_mean_directional_gain": float(np.mean([np.linalg.norm(v) for v in derivative_vectors])),
            "local_jacobian_max_directional_gain": float(np.max([np.linalg.norm(v) for v in derivative_vectors])),
            "n_directions": int(len(derivative_vectors)),
        })
    df_strict_jacobian_spectral_raw = pd.DataFrame(spectral_rows)
    save_df(df_strict_jacobian_spectral_raw, "strict_local_jacobian_spectral_raw.csv")

    jacobian_summary_rows = []
    for keys, group in df_strict_jacobian_spectral_raw.groupby(["start_kind", "recovery_turns", "hidden_index", "module_layer", "perturb_hidden_index", "perturb_module_layer"]):
        spectral = bootstrap_mean(group["local_jacobian_spectral_norm"].to_numpy(), group["index"].to_numpy())
        max_gain = bootstrap_mean(group["local_jacobian_max_directional_gain"].to_numpy(), group["index"].to_numpy())
        mean_gain = bootstrap_mean(group["local_jacobian_mean_directional_gain"].to_numpy(), group["index"].to_numpy())
        jacobian_summary_rows.append({
            "start_kind": keys[0],
            "recovery_turns": int(keys[1]),
            "hidden_index": int(keys[2]),
            "module_layer": int(keys[3]),
            "perturb_hidden_index": int(keys[4]),
            "perturb_module_layer": int(keys[5]),
            "local_jacobian_spectral_norm_mean": spectral["mean"],
            "local_jacobian_spectral_norm_ci_low": spectral["ci_low"],
            "local_jacobian_spectral_norm_ci_high": spectral["ci_high"],
            "local_jacobian_max_directional_gain_mean": max_gain["mean"],
            "local_jacobian_max_directional_gain_ci_low": max_gain["ci_low"],
            "local_jacobian_max_directional_gain_ci_high": max_gain["ci_high"],
            "local_jacobian_mean_directional_gain_mean": mean_gain["mean"],
            "local_jacobian_mean_directional_gain_ci_low": mean_gain["ci_low"],
            "local_jacobian_mean_directional_gain_ci_high": mean_gain["ci_high"],
            "n_units": spectral["n_units"],
            "n_rows": spectral["n_rows"],
        })
    df_strict_jacobian_summary = pd.DataFrame(jacobian_summary_rows)
    save_df(df_strict_jacobian_summary, "strict_local_jacobian_summary.csv")


def single_row(df: pd.DataFrame, mask) -> pd.Series | None:
    work = df[mask]
    if work.empty:
        return None
    return work.iloc[0]


def finite_bool(value: Any) -> bool:
    try:
        return bool(np.isfinite(float(value)))
    except Exception:
        return False


